package com.suks.sittiporn.lslamic.forgetpassword;import androidx.appcompat.app.AppCompatActivity;import android.os.Bundle;import android.view.MenuItem;import com.suks.sittiporn.lslamic.R;import com.suks.sittiporn.lslamic.forgetpassword.forgetemail.ForgetEmailFragment;import com.suks.sittiporn.lslamic.util.BaseActivity;public class ForgetPasswordActivity extends BaseActivity {    @Override    public void onCreate(Bundle savedInstanceState) {        super.onCreate(savedInstanceState);        setContentView(R.layout.forget_password_activity);        getSupportActionBar().setDisplayHomeAsUpEnabled(true);        getSupportActionBar().setDisplayShowCustomEnabled(true);        if (savedInstanceState == null) {            getSupportFragmentManager().beginTransaction()                    .replace(R.id.container, ForgetPasswordFragment.newInstance())                    .commitNow();        }    }    @Override    public boolean onOptionsItemSelected(MenuItem item) {        onBackPressed();        return true;    }    @Override    public void onBackPressed() {        super.onBackPressed();    }}